.section .text
.global dense

# Function: dense
# Arguments:
#   a0 - address of input vector
# Returns:
#   a0 - address of output vector
dense:
    addi sp, sp, -8
    sw ra, 0(sp)
    sw a0, 4(sp)                # Save input vector pointer

    la t3, D_IN_DIM
    lw t0, 0(t3)                # D_IN_DIM (e.g. 1152)
    lw t1, 4(t3)                # D_OUT_DIM (e.g. 10)

    la a2, weights               # weights pointer
    la a3, biases                # biases pointer
    la a4, outputs               # output buffer

    addi t2, zero, 0             # i = 0
    loop_i:
        bge t2, t1, end_loop_i       # if i >= D_OUT_DIM, break

        vsetivli t3, 1, e32, ta, ma
        flw f1, 0(a3)  
        vfmv.s.f v5, f1              # broadcast bias[i]

        mv t6, t0                # t6 = D_IN_DIM (input size)
        mv s3, a0                # s3 = input vector pointer
        dense_inner:
            vsetvli t5, t6, e32, ta, ma
            sub t6, t6, t5               # remaining input elements
            slli s1, t5, 2               # vector byte length

            vle32.v v1, (s3)             # v1 = input[j]
            add s3, s3, s1               # move input pointer forward

            vle32.v v2, (a2)             # v2 = weights[j][i]
            add a2, a2, s1               # move weights pointer forward

            vfmul.vv v3, v1, v2          # v3 = input * weights
            vfredosum.vs v5, v3, v5      # v5 += sum(v3)

            bnez t6, dense_inner         # continue if not done

        dense_done:
            vfmv.f.s f0, v5
            fsw f0, 0(a4)                # store result

            addi a4, a4, 4               # move output pointer
            addi a3, a3, 4               # next bias
            addi t2, t2, 1               # i++

            j loop_i

    end_loop_i:
        la a0, outputs               # return output pointer in a0

    lw ra, 0(sp)
    addi sp, sp, 8
    ret

.data 

D_IN_DIM:   .word 1152
D_OUT_DIM:  .word 10


